    id: "tech89",
    domain: "cloud-technology-and-services",
    text: "A team runs several low-traffic development web servers and a small CI runner. CPU sits near idle most of the day with occasional short spikes during builds. The team wants the lowest-cost EC2 option that still handles the spikes. Which instance family should it choose?",
    options: [
      { id: "a", text: "Burstable performance instances (T family, such as t3 or t4g)" },
      { id: "b", text: "Compute optimized instances (C family)" },
      { id: "c", text: "Memory optimized instances (R family)" },
      { id: "d", text: "Accelerated computing instances (P family)" },
    ],
    correctOptionIds: ["a"],
    explanation: "T-family instances provide a baseline level of CPU with the ability to burst above it using accumulated CPU credits, making them the most economical choice for workloads that are idle most of the time with short spikes.",
    optionRationale: {
      a: "Burstable instances are priced for low baseline usage and bank credits while idle to spend during builds.",
      b: "C instances are built for sustained CPU-heavy work and cost more than needed for mostly idle servers.",
      c: "R instances optimize for large memory footprints, which is not the constraint here.",
      d: "P instances carry GPUs for machine learning and are far more expensive than the workload warrants.",
    },
    referenceUrl: "https://docs.aws.amazon.com/ec2/latest/instancetypes/gp.html#gp_burstable",
