    optionRationale: {
      a: "With Fargate you specify CPU and memory per task or pod and AWS provisions the compute automatically.",
      b: "Both ECS and EKS support Fargate so workloads can be scheduled without managing worker nodes.",
      c: "AWS patches and maintains the hosts; that is a key benefit of Fargate over the EC2 launch type.",
      d: "Amazon ECR is the container registry; Fargate runs containers.",
      e: "Fargate runs in AWS Regions; it is not restricted to Outposts.",
    },
