    correctOptionIds: ["a"],
    explanation: "A target tracking scaling policy works like a thermostat: you choose a metric and target value, such as 50 percent average CPU, and Auto Scaling creates the CloudWatch alarms and adjusts capacity to keep the metric near the target.",
    optionRationale: {
      a: "Target tracking automatically scales in and out to maintain the chosen metric at the specified target value.",
      b: "Scheduled actions change capacity at fixed times, not in response to CPU utilization.",
      c: "Manual scaling requires an operator to change desired capacity by hand.",
      d: "Lifecycle hooks run custom actions during instance launch or termination; they do not decide when to scale.",
    },
