    text: "A security team wants to insert a fleet of third-party virtual firewall appliances from AWS Marketplace into the network path so that all traffic entering several VPCs is transparently inspected, with the appliances scaled and health-checked automatically. Which type of Elastic Load Balancer is designed for this use case?",
