    id: "tech138",
    domain: "cloud-technology-and-services",
    text: "A company has a VPC for its web tier and a separate VPC for a shared database, both in the same Region. It wants the two VPCs to communicate privately over the AWS network using private IP addresses. Which TWO statements about using VPC peering for this scenario are correct?",
    options: [
      { id: "a", text: "VPC peering connections are not transitive; a third VPC peered to the web VPC cannot reach the database VPC through it" },
      { id: "b", text: "The two VPCs must not have overlapping CIDR blocks" },
      { id: "c", text: "VPC peering requires an internet gateway in each VPC" },
      { id: "d", text: "VPC peering only works between VPCs in the same AWS account" },
      { id: "e", text: "Traffic over a VPC peering connection traverses the public internet" },
    ],
    correctOptionIds: ["a", "b"],
    explanation: "VPC peering creates a one-to-one networking connection between two VPCs using private IPs over the AWS backbone. It is non-transitive, requires non-overlapping CIDR ranges, and works across accounts and Regions.",
    optionRationale: {
      a: "Peering is strictly point-to-point; you must peer each pair of VPCs (or use Transit Gateway for hub-and-spoke).",
      b: "Overlapping CIDR blocks prevent a peering connection from being established because routes would be ambiguous.",
      c: "No internet gateway is needed; traffic stays on the AWS private network.",
      d: "Peering supports VPCs in different accounts and different Regions (inter-Region peering).",
      e: "Peering traffic never leaves the AWS global network.",
    },
    referenceUrl: "https://docs.aws.amazon.com/vpc/latest/peering/what-is-vpc-peering.html",
