    domain: "cloud-technology-and-services",
    text: "A manufacturer deploys cameras and sensors on factory floors with intermittent internet connectivity. It needs devices to run local machine learning inference and Lambda functions at the edge, keep operating while offline, and sync with the cloud when connectivity returns. Which TWO statements about the relevant AWS IoT services are correct?",
    options: [
      { id: "a", text: "AWS IoT Greengrass extends AWS to edge devices so they can run local compute, messaging, and ML inference even when disconnected" },
      { id: "b", text: "AWS IoT Core acts as the cloud message broker that devices connect to securely over MQTT and other protocols" },
      { id: "c", text: "AWS IoT Greengrass requires a permanent internet connection to execute any code" },
      { id: "d", text: "AWS IoT Core stores time-series data for years and is a replacement for Amazon Timestream for InfluxDB" },
      { id: "e", text: "AWS Snowmobile is the recommended way to send sensor messages to the cloud" },
    ],
    correctOptionIds: ["a", "b"],
    explanation: "AWS IoT Greengrass is an open-source edge runtime and cloud service that lets devices act locally on the data they generate, run Lambda functions and ML models, and sync with the cloud. AWS IoT Core is the managed cloud service that connects devices securely and routes their messages to other AWS services.",
