    id: "tech154",
    domain: "cloud-technology-and-services",
    text: "A company serves its website through Amazon CloudFront. It wants to run a tiny piece of JavaScript at the edge on every request to rewrite URLs and add security headers, with sub-millisecond latency and at very high request volumes. Which CloudFront feature is the most cost-effective fit?",
    options: [
      { id: "a", text: "CloudFront Functions" },
      { id: "b", text: "Lambda@Edge" },
      { id: "c", text: "An origin request policy" },
      { id: "d", text: "CloudFront origin access control" },
    ],
    correctOptionIds: ["a"],
    explanation: "CloudFront Functions is a lightweight JavaScript runtime that executes at CloudFront edge locations with sub-millisecond startup times, designed for high-volume, simple tasks such as header manipulation, URL rewrites, and redirects. It is cheaper and faster than Lambda@Edge for these use cases.",
    optionRationale: {
      a: "CloudFront Functions is purpose-built for lightweight, latency-sensitive request and response manipulations at scale.",
      b: "Lambda@Edge runs full Lambda functions at Regional edge caches and suits heavier logic such as network calls, but costs more and has higher latency.",
      c: "Origin request policies control which headers, cookies, and query strings are forwarded; they do not run custom code.",
      d: "Origin access control restricts S3 origins to be reachable only via CloudFront.",
    },
    referenceUrl: "https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/cloudfront-functions.html",
    referenceLabel: "Customizing at the edge with CloudFront Functions",
