    consoleLabel: "CloudFront > Functions",
    diagram: "flowchart LR\n  Viewer --> Edge[CloudFront edge location]\n  Edge --> Fn[\"CloudFront Function (rewrite URL, add headers)\"]\n  Fn --> Cache[CloudFront cache]\n  Cache --> Origin[S3 or ALB origin]",
    cliExample: {
      description: "List CloudFront Functions",
      command: "aws cloudfront list-functions --query \"FunctionList.Items[].{Name:Name,Stage:FunctionMetadata.Stage,Status:Status}\"",
      sampleOutput: "[\n  {\n    \"Name\": \"add-security-headers\",\n    \"Stage\": \"LIVE\",\n    \"Status\": \"DEPLOYED\"\n  }\n]",
    },
