    text: "A company wants to give its employees a generative AI assistant that can answer questions, summarize documents, and draft content using the company's own data stored in SharePoint, Confluence, Salesforce, and Amazon S3, while respecting each employee's existing access permissions. The company does not want to build or host any models. Which AWS service best meets this requirement?",
