    text: "An e-commerce application must send order confirmations, password reset messages, and a weekly marketing newsletter by email to millions of customers. The company wants a scalable, pay-as-you-go email sending service with high deliverability, bounce and complaint tracking, and support for SMTP and API sending. Which AWS service should it use?",
