    consoleUrl: "https://console.aws.amazon.com/s3/home",
    consoleLabel: "Amazon S3 > Buckets",
    diagram: "flowchart TD\n  Q1[Accessed infrequently?] -->|yes| Q2[Can data be re-created?]\n  Q2 -->|yes| OZ[S3 One Zone-IA - single AZ, lowest IA price]\n  Q2 -->|no| SIA[S3 Standard-IA - three or more AZs]\n  Q1 -->|no| STD[S3 Standard]",
