    id: "tech165",
    domain: "cloud-technology-and-services",
    text: "An analytics team needs a data warehouse for ad hoc SQL queries over terabytes of sales data. Query volume is unpredictable, with some days having no queries at all. The team does not want to choose node types, size a cluster, or pay for idle capacity. Which option best fits?",
    options: [
      { id: "a", text: "Amazon Redshift Serverless" },
      { id: "b", text: "A provisioned Amazon Redshift cluster with reserved nodes" },
      { id: "c", text: "Amazon RDS for PostgreSQL Multi-AZ" },
      { id: "d", text: "Amazon DynamoDB with on-demand capacity" },
    ],
    correctOptionIds: ["a"],
    explanation: "Amazon Redshift Serverless automatically provisions and scales data warehouse capacity, measured in Redshift Processing Units, to run analytics workloads. You pay only for the compute used while queries run, with no cluster to size or manage, which suits intermittent and unpredictable query patterns.",
    optionRationale: {
      a: "Redshift Serverless removes cluster sizing and node selection and bills only for capacity consumed while queries are running.",
      b: "A provisioned cluster with reserved nodes commits you to paying for capacity around the clock, wasting money on idle days.",
      c: "RDS for PostgreSQL is an OLTP relational database, not a columnar data warehouse for large analytical scans.",
      d: "DynamoDB is a NoSQL key-value store and does not support ad hoc analytical SQL across terabytes of data.",
    },
    referenceUrl: "https://docs.aws.amazon.com/redshift/latest/mgmt/serverless-whatis.html",
