    id: "tech166",
    domain: "cloud-technology-and-services",
    text: "A company built a customer support chatbot on a foundation model in Amazon Bedrock. The model sometimes gives generic or outdated answers because it has no knowledge of the company's internal product manuals stored in Amazon S3. The company wants the model's responses to be grounded in those documents using retrieval augmented generation (RAG) without training a custom model. Which Bedrock capability should it use?",
    options: [
      { id: "a", text: "Amazon Bedrock Knowledge Bases" },
      { id: "b", text: "Amazon Bedrock Guardrails" },
      { id: "c", text: "Amazon Bedrock model customization by fine-tuning" },
      { id: "d", text: "Amazon Bedrock Provisioned Throughput" },
    ],
    correctOptionIds: ["a"],
    explanation: "Amazon Bedrock Knowledge Bases implement the full RAG workflow: they ingest documents from sources such as Amazon S3, convert them into embeddings stored in a vector store, retrieve the most relevant passages at query time, and augment the model prompt with that context so responses cite current, company-specific information.",
    optionRationale: {
      a: "Knowledge Bases connect data sources to a vector store and perform retrieval augmented generation for grounded answers.",
      b: "Guardrails filter harmful content, block denied topics, and redact sensitive data; they do not add knowledge to the model.",
      c: "Fine-tuning creates a customized model from training data, which is costlier, slower to update, and not what the company asked for.",
      d: "Provisioned Throughput reserves model inference capacity for consistent performance; it does not change what the model knows.",
    },
    referenceUrl: "https://docs.aws.amazon.com/bedrock/latest/userguide/knowledge-base.html",
    referenceLabel: "Amazon Bedrock Knowledge Bases",
