    text: "A platform team wants to verify that its application on Amazon EC2 and Amazon RDS really tolerates failures. It wants to run controlled experiments such as terminating instances, injecting CPU stress, and simulating an Availability Zone power interruption, with automatic stop conditions if key CloudWatch alarms fire. Which AWS service is designed for this?",
