    text: "A bank runs core banking applications written in COBOL on an IBM mainframe. It wants to move these workloads to AWS, either by refactoring the COBOL into Java or by replatforming the applications onto a managed runtime environment in the cloud, using a set of tools and services designed specifically for this journey. Which AWS service should it evaluate?",
