    correctOptionIds: ["a"],
    explanation: "S3 Express One Zone is a high-performance, single-Availability Zone storage class that uses directory buckets and delivers consistent single-digit millisecond first-byte latency, up to 10 times faster than S3 Standard, for performance-critical applications. Placing the directory bucket in the same Availability Zone as the compute minimizes latency further.",
